{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01Rssk5L2vz7iit6HGCwh6LZ","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01WZrdZtwjVLKvYf42jc3xfZ","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"westd-34142","command":"cat > /root/meta_brain_lora_routing/phase0/collect_activations_v2.py << 'SCRIPT'\n\"\"\"\nCollect per-step pi0_libero activations for PAR Router v2 retraining.\n\nSaves per-replan-point activations (not averaged) in the same format\nas activations/per_step/*.pt for direct use with train_par_router.py.\n\nUsage:\n    cd /root/meta_brain_lora_routing/phase0\n    python collect_activations_v2.py \\\n        --checkpoint /root/autodl-tmp/checkpoints/pi0_libero \\\n        --output_dir /root/meta_brain_lora_routing/activations_v2/per_step \\\n        --perturbation_type all \\\n        --num_episodes 25 \\\n        --device cuda:1\n\"\"\"\n\nimport argparse\nimport collections\nimport logging\nimport random\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\n\nfrom configs import (\n    CLASS_6_TO_3_MAPPING,\n    PERTURBATION_TYPES_6CLASS,\n)\nfrom libero_integration import (\n    create_libero_env,\n    load_pi0_for_collection,\n    obs_to_model_input,\n    LIBERO_DUMMY_ACTION,\n    MAX_STEPS,\n    DEFAULT_REPLAN_STEPS,\n    DEFAULT_NUM_STEPS_WAIT,\n)\n\nlog = logging.getLogger(__name__)\n\n\ndef run_episode_per_step(\n    policy,\n    collector,\n    perturbation_type: str | None,\n    device: str,\n    task_suite: str = \"libero_spatial\",\n    seed: int = 42,\n    replan_steps: int = DEFAULT_REPLAN_STEPS,\n    num_steps_wait: int = DEFAULT_NUM_STEPS_WAIT,\n) -> dict:\n    \"\"\"Run one episode, returning per-step activations (not averaged).\"\"\"\n    env, task_description, init_states, task_idx = create_libero_env(\n        task_suite_name=task_suite,\n        perturbation_type=perturbation_type,\n        seed=seed,\n    )\n    max_steps = MAX_STEPS.get(task_suite, 400)\n    step = 0\n    success = False\n\n    try:\n        trial_idx = random.randint(0, len(init_states) - 1)\n        obs = env.set_init_state(init_states[trial_idx])\n\n        for _ in range(num_steps_wait):\n            obs, _, _, _ = env.step(LIBERO_DUMMY_ACTION)\n\n        action_plan = collections.deque()\n        step_activations = []\n        done = False\n\n        while not done and step < max_steps:\n            if len(action_plan) == 0:\n                collector.clear()\n                obs_dict = obs_to_model_input(obs, task_description)\n                result = policy.infer(obs_dict)\n                action_chunk = result[\"actions\"]\n                action_plan.extend(action_chunk[:replan_steps])\n\n                pooled = collector.get_pooled()\n                if pooled:\n                    step_activations.append(pooled)\n\n            action = action_plan.popleft()\n            if isinstance(action, torch.Tensor):\n                action = action.cpu().numpy()\n            obs, reward, done, info = env.step(\n                action.tolist() if hasattr(action, \"tolist\") else list(action)\n            )\n            step += 1\n            if done or reward > 0:\n                success = info.get(\"success\", reward > 0)\n    finally:\n        env.close()\n\n    return {\n        \"step_activations\": step_activations,\n        \"num_replan_points\": len(step_activations),\n        \"task_name\": f\"{task_suite}/task_{task_idx}\",\n        \"task_description\": task_description,\n        \"num_steps\": step,\n        \"success\": success,\n    }\n\n\ndef make_labels(perturbation_type: str) -> dict:\n    if perturbation_type == \"nominal\":\n        return {\"label_6class\": -1, \"label_3class\": -1, \"label_binary\": 0}\n    label_6 = PERTURBATION_TYPES_6CLASS[perturbation_type]\n    label_3 = CLASS_6_TO_3_MAPPING[label_6]\n    return {\"label_6class\": label_6, \"label_3class\": label_3, \"label_binary\": 1}\n\n\ndef collect(args):\n    random.seed(args.seed)\n    np.random.seed(args.seed)\n    torch.manual_seed(args.seed)\n\n    device = args.device\n    output_dir = Path(args.output_dir)\n    output_dir.mkdir(parents=True, exist_ok=True)\n\n    log.info(\"Loading pi0_libero from %s on %s\", args.checkpoint, device)\n    policy, model = load_pi0_for_collection(args.checkpoint, device)\n\n    from collect_activations import ActivationCollector\n    collector = ActivationCollector(model)\n    collector.register_hooks()\n\n    if args.perturbation_type == \"all\":\n        perturbation_types = list(PERTURBATION_TYPES_6CLASS.keys())\n    else:\n        perturbation_types = [args.perturbation_type]\n\n    for ptype in perturbation_types:\n        is_nominal = ptype == \"nominal\"\n        log.info(\"Collecting %d episodes for %s\", args.num_episodes, ptype)\n        episodes = []\n\n        for ep_idx in range(args.num_episodes):\n            log.info(\"  Episode %d/%d\", ep_idx + 1, args.num_episodes)\n            try:\n                result = run_episode_per_step(\n                    policy, collector,\n                    perturbation_type=None if is_nominal else ptype,\n                    device=device,\n                    task_suite=args.task_suite,\n                    seed=args.seed + ep_idx,\n                )\n            except Exception:\n                log.exception(\"Episode %d failed, skipping\", ep_idx)\n                continue\n\n            labels = make_labels(ptype)\n            episode_data = {\n                \"step_activations\": result[\"step_activations\"],\n                \"num_replan_points\": result[\"num_replan_points\"],\n                **labels,\n                \"metadata\": {\n                    \"perturbation_type\": ptype,\n                    \"task_name\": result[\"task_name\"],\n                    \"num_steps\": result[\"num_steps\"],\n                    \"success\": result[\"success\"],\n                    \"episode_idx\": ep_idx,\n                },\n          