{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01Ht2iG956ig42iFxPjY7v6z","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01EdhHMtigtQj7S813377E9V","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"westd-34142","command":"cat > /root/meta_brain_lora_routing/phase0/collect_activations_v2.py << 'SCRIPT'\n\"\"\"\nCollect per-step pi0_libero activations for PAR Router v2 retraining.\nHandles LeRobot-format checkpoint (model.* prefix) by stripping prefix.\n\"\"\"\n\nimport argparse\nimport collections\nimport logging\nimport os\nimport random\nimport sys\nimport types\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nimport safetensors.torch\n\nfrom configs import (\n    CLASS_6_TO_3_MAPPING,\n    PERTURBATION_TYPES_6CLASS,\n)\n\nlog = logging.getLogger(__name__)\n\n\ndef _ensure_openpi_imports():\n    for mod in [\n        \"lerobot\", \"lerobot.common\", \"lerobot.common.datasets\",\n        \"lerobot.common.datasets.lerobot_dataset\",\n    ]:\n        if mod not in sys.modules:\n            sys.modules[mod] = types.ModuleType(mod)\n\n\ndef load_pi0_libero(checkpoint_path: str, device: str):\n    \"\"\"Load pi0_libero with model.* prefix stripping, bypassing norm_stats.\"\"\"\n    _ensure_openpi_imports()\n\n    from openpi.training import config as _config\n    from openpi.models_pytorch import pi0_pytorch\n    import openpi.policies.policy as _policy\n    import openpi.transforms as transforms\n\n    train_config = _config.get_config(\"pi0_libero\")\n\n    # Create model and load weights with prefix stripping\n    model = pi0_pytorch.PI0Pytorch(config=train_config.model)\n    weight_path = os.path.join(checkpoint_path, \"model.safetensors\")\n    tensors = safetensors.torch.load_file(weight_path)\n\n    skip_prefixes = ('normalize_inputs.', 'normalize_targets.', 'unnormalize_outputs.')\n    cleaned = {}\n    for k, v in tensors.items():\n        if any(k.startswith(p) for p in skip_prefixes):\n            continue\n        cleaned[k.removeprefix('model.')] = v\n\n    missing, unexpected = model.load_state_dict(cleaned, strict=False)\n    if missing:\n        log.warning(\"Missing keys: %d (%s)\", len(missing), missing[:3])\n    if unexpected:\n        log.warning(\"Unexpected keys: %d\", len(unexpected))\n\n    model.paligemma_with_expert.to_bfloat16_for_selected_params(\"bfloat16\")\n\n    # Build policy with minimal transforms (no norm_stats for activation collection)\n    data_config = train_config.data.create(train_config.assets_dirs, train_config.model)\n\n    policy = _policy.Policy(\n        model,\n        transforms=[\n            *data_config.data_transforms.inputs,\n            transforms.Normalize(None, use_quantiles=False),\n            *data_config.model_transforms.inputs,\n        ],\n        output_transforms=[\n            *data_config.model_transforms.outputs,\n            transforms.Unnormalize(None, use_quantiles=False),\n            *data_config.data_transforms.outputs,\n        ],\n        is_pytorch=True,\n        pytorch_device=device,\n    )\n\n    log.info(\"Loaded pi0_libero on %s (missing=%d keys)\", device, len(missing))\n    return policy, model\n\n\nfrom libero_integration import (\n    create_libero_env,\n    obs_to_model_input,\n    LIBERO_DUMMY_ACTION,\n    MAX_STEPS,\n    DEFAULT_REPLAN_STEPS,\n    DEFAULT_NUM_STEPS_WAIT,\n)\nfrom collect_activations import ActivationCollector\n\n\ndef run_episode_per_step(\n    policy, collector, perturbation_type, device,\n    task_suite=\"libero_spatial\", seed=42,\n    replan_steps=DEFAULT_REPLAN_STEPS,\n    num_steps_wait=DEFAULT_NUM_STEPS_WAIT,\n):\n    env, task_description, init_states, task_idx = create_libero_env(\n        task_suite_name=task_suite,\n        perturbation_type=perturbation_type,\n        seed=seed,\n    )\n    max_steps = MAX_STEPS.get(task_suite, 400)\n    step = 0\n    success = False\n\n    try:\n        trial_idx = random.randint(0, len(init_states) - 1)\n        obs = env.set_init_state(init_states[trial_idx])\n\n        for _ in range(num_steps_wait):\n            obs, _, _, _ = env.step(LIBERO_DUMMY_ACTION)\n\n        action_plan = collections.deque()\n        step_activations = []\n        done = False\n\n        while not done and step < max_steps:\n            if len(action_plan) == 0:\n                collector.clear()\n                obs_dict = obs_to_model_input(obs, task_description)\n                result = policy.infer(obs_dict)\n                action_chunk = result[\"actions\"]\n                action_plan.extend(action_chunk[:replan_steps])\n\n                pooled = collector.get_pooled()\n                if pooled:\n                    step_activations.append(pooled)\n\n            action = action_plan.popleft()\n            if isinstance(action, torch.Tensor):\n                action = action.cpu().numpy()\n            obs, reward, done, info = env.step(\n                action.tolist() if hasattr(action, \"tolist\") else list(action)\n            )\n            step += 1\n            if done or reward > 0:\n                success = info.get(\"success\", reward > 0)\n    finally:\n        env.close()\n\n    return {\n        \"step_activations\": step_activations,\n        \"num_replan_points\": len(step_activations),\n        \"task_name\": f\"{task_suite}/task_{task_idx}\",\n        \"task_description\": task_description,\n        \"num_steps\": step,\n        \"success\": success,\n    }\n\n\ndef make_labels(perturbation_type):\n    if perturbation_type == \"nominal\":\n        return {\"label_6class\": -1, \"label_3class\": -1, \"label_binary\": 0}\n    label_6 = PERTURBATION_TYPES_6CLASS[perturbation_type]\n    label_3 = CLASS_6_TO_3_MAPPING[label_6]\n    return {\"label_6class\": label_6, \"label_3class\": label_3, \"label_binary\": 1}\n\n\ndef collect(args):\n    random.seed(args.seed)\n    np.random.seed(args.seed)\n    torch.manual_seed(args.seed)\n\n    output_dir = Path(args.output_dir)\n    output_dir.mkdir(parents=True, exist_ok=True)\n\n    log.info(\"Loading pi0_libero from %s on %s\", args.checkpoint, args.device)\n    policy, model = load_pi0_libero(args.checkpoint, args.device)\n\n    collector = ActivationCollector(model)\n    collector.register_hooks()\n\n    if args.perturbation_type == \"all\":\n        perturbation_types = list(PERTURBATION_TYPES_6CLASS.keys())\n    else:\n        perturbation_types = [args.perturbation_type]\n\n    for ptype in perturbation_types:\n        is_nominal = ptype == \"nominal\"\n        log.info(\"Collecting %d episodes for %s\", args.num_episodes, ptype)\n        episodes = []\n\n        for ep_idx in range(args.num_episodes):\n            log.info(\"  Episode %d/%d\", ep_idx + 1, args.num_episodes)\n            try:\n                result = run_episode_per_step(\n                    policy, collector,\n                    perturbation_type=None if is_nominal else ptype,\n                    device=args.device,\n                    task_suite=args.task_suite,\n                    seed=args.seed + ep_idx,\n                )\n            except Exception:\n                log.exception(\"Episode %d failed, skipping\", ep_idx)\n                continue\n\n            labels = make_labels(ptype)\n            episode_data = {\n                \"step_activations\": result[\"step_activations\"],\n                \"num_replan_points\": result[\"num_replan_points\"],\n                **labels,\n                \"metadata\": {\n                    \"perturbation_type\": ptype,\n                    \"task_name\": result[\"task_name\"],\n                    \"num_steps\": result[\"num_steps\"],\n                    \"success\": result[\"success\"],\n                    \"episode_idx\": ep_idx,\n                },\n            }\n            episodes.append(episode_data)\n\n        save_path = output_dir / f\"{ptype}.pt\"\n        torch.save(episodes, save_path)\n        total_steps = sum(ep[\"num_replan_points\"] for ep in episodes)\n        log.info(\"Saved %s: %d episodes, %d total steps\", save_path, len(episodes), total_steps)\n\n    collector.remove_hooks()\n    log.info(\"Collection complete.\")\n\n\nif __name__ == \"__main__\":\n    logging.basicConfig(\n        level=logging.INFO,\n        format=\"%(asctime)s [%(levelname)s] %(name)s: %(message)s\",\n    )\n    p = argparse.ArgumentParser()\n    p.add_argument(\"--checkpoint\", type=str,\n                   default=\"/root/autodl-tmp/checkpoints/pi0_libero\")\n    p.add_argument(\"--output_dir\", type=str,\n                   default=\"/root/meta_brain_lora_routing/activations_v2/per_step\")\n    valid_types = list(PERTURBATION_TYPES_6CLASS.keys()) + [\"all\", \"nominal\"]\n    p.add_argument(\"--perturbation_type\", type=str, default=\"all\", choices=valid_types)\n    p.add_argument(\"--num_episodes\", type=int, default=25)\n    p.add_argument(\"--task_suite\", type=str, default=\"libero_spatial\",\n                   choices=[\"libero_spatial\", \"libero_object\", \"libero_goal\", \"libero_10\", \"libero_90\"])\n    p.add_argument(\"--device\", type=str, default=\"cuda:1\")\n    p.add_argument(\"--seed\", type=int, default=42)\n    args = p.parse_args()\n    collect(args)\nSCRIPT","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":313,"cache_read_input_tokens":83994,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":313},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"436bc48d-6197-44c5-bb0b-d9d9fb2582a8","uuid":"15146b4f-8f94-4b8e-bcbf-f2d4077b0b53"}
